                    <span class="sp-b-section-count">
                      {group.entities.length}{" "}
                      {group.entities.length === 1 ? "entity" : "entities"}
                    </span>
                  </th>
                </tr>
                <For each={group.entities}>
                  {(entity) => (
                    <>
                      <tr
                        class="sp-b-entity-row"
