        </button>
        <For
          each={operations.filter((status) =>
            props.fixture.entities.some((entity) => entity.status === status),
          )}
        >
          {(status) => (
            <button
              classList={{ "sp-b-active": operation() === status }}
              aria-pressed={operation() === status}
