                          <span class={`sp-b-status sp-b-${entity.status}`}>
                            {entity.status}
                          </span>
                        </td>
                        <td class="sp-b-identity">
                          <button
                            onClick={() =>
                              setExpanded((previous) => {
                                const next = new Set(previous);
                                if (next.has(entity.id)) {
                                  next.delete(entity.id);
                                } else {
                                  next.add(entity.id);
                                }
                                return next;
                              })
