                }}
                title={entity.name}
              >
                <span class="sp-c-node-kind">
                  {entity.kind}
                  <span data-status={entity.status}>{entity.status}</span>
                </span>
                <strong>{entity.name}</strong>
                <small title={entity.path}>{entity.path}</small>
              </button>
            );
