              <For each={orderedFiles}>
                {(file, fileIndex) => {
                  return (
                    <FileCard
                      reviewFile={{
                        left_path: file.entry.left_path,
                        right_path: file.entry.right_path,
                      }}
                      file_state={lane.fileState(fileIndex())}
                      expanded={fileExpanded(
                        file,
                        lane.fileState(fileIndex()),
                        props.state.fileExpansion,
